// th18_s3_w08: TH18 v1.00a Stage 3 MainSub07 -> GirlD02.
// Source: st03.ecl.txt:1244-1248 (create), 813-892 (GirlD02 / GirlD02_at).
const TIME_LIMIT: int = 4600;
const TH18_RICE: int = 480;

// GirlD02_at etEx type 0x200000 (VELTIME): a=60, r=3.0, s=-9999994 keeps
// the bullet angle; initial ring speed is etSpeed s0=1.2 with one layer.
xformdef RAMP(target: fx) {
    set_gravity(at_spawn(((target - 1.2fx) / 60fx) * cos($self_angle)),
                at_spawn(((target - 1.2fx) / 60fx) * sin($self_angle)));
    @60 add_speed(0fx);
    set_gravity(0fx, 0fx);
}

async sub shots() {
    wait(60);                              // source wait(60)
    var rank: int = global(GVAR_RANK);
    var count: int = 25;                   // E
    var gap: int = 150;                    // E/N
    if rank == 1 { count = 40; }           // N
    if rank == 2 { count = 50; gap = 120; }// H
    if rank == 3 { count = 60; gap = 90; } // L

    // GirlD02_at emitter: mode10, one layer => fixed ring alpha + i*360/N;
    // each ring is emitted from a radius-64 polar offset.
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 4);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, count, 1);
    sh_speed(0, 1.2fx, 0fx);
    sh_dist(0, -4.8fx);                    // ANIM a=1: position -= 4*velocity
    sh_xform(0, RAMP(3fx));

    for volley in 0..20 {                  // $B=20, 20 bodies
        sh_offset_rad(0, -90deg, 64fx);    // -1.5707964 rad
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, -18deg, 64fx);    // -0.31415927 rad
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, 54deg, 64fx);     // 0.9424778 rad
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, 126deg, 64fx);    // 2.1991148 rad
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, 198deg, 64fx);    // 3.455752 rad
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        wait(gap);
    }
}

async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);                     // source setHurtbox(32,32)
    set_hitbox(12fx);                      // source setHitbox(24,24)
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn shots();
    wait(4000);                            // explicit source wait
    move_speed(120, 2fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

async sub wave() {
    wait(120);                             // training-shell opening buffer
    _ = spawn_enemy(0fx, -48fx, 10000, 0, 1000, 16, girl);
    loop { wait(600); }
}

async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
